1	package vault
2	
3	import (
4		"crypto/sha256"
5		"encoding/hex"
6		"encoding/json"
7		"errors"
8		"fmt"
9		"io"
10		"os"
11		"path/filepath"
12		"sort"
13		"strings"
14		"syscall"
15		"time"
16	)
17	
18	type Entry struct {
19		Name      string    `json:"name"`
20		Digest    string    `json:"digest"`
21		Size      int64     `json:"size"`
22		CreatedAt time.Time `json:"createdAt"`
23	}
24	
25	type index struct {
26		Entries map[string]Entry `json:"entries"`
27	}
28	
29	type Store struct{ root string }
30	
31	func New(root string) *Store { return &Store{root: root} }
32	
33	// withLock serializes access to the repository across cooperating processes.
34	// Mutating operations pass exclusive=true; readers take a shared lock. The
35	// lock is an flock on <root>/.lock, so it is released automatically if a
36	// process dies mid-operation and nothing can wait forever on a stale lock.
37	func (s *Store) withLock(exclusive bool, fn func() error) error {
38		return s.withLockOpts(exclusive, true, fn)
39	}
40	
41	// withLockOpts is withLock with control over root creation. Read-only-style
42	// operations that must never materialize a missing repository (such as
43	// export) pass createRoot=false.
44	func (s *Store) withLockOpts(exclusive, createRoot bool, fn func() error) error {
45		if strings.TrimSpace(s.root) == "" {
46			return errors.New("root is required")
47		}
48		if createRoot {
49			if err := os.MkdirAll(s.root, 0o755); err != nil {
50				return err
51			}
52		}
53		// Read-only operations that must not materialize anything open the lock
54		// without O_CREATE: an initialized repository always has a lock file, so
55		// a missing one means the repository was never initialized.
56		var lock *os.File
57		var err error
58		if createRoot {
59			lock, err = os.OpenFile(s.lockPath(), os.O_CREATE|os.O_RDWR, 0o644)
60		} else {
61			lock, err = os.OpenFile(s.lockPath(), os.O_RDWR, 0o644)
62		}
63		if err != nil {
64			if !createRoot && errors.Is(err, os.ErrNotExist) {
65				return fmt.Errorf("repository %q is not initialized; run init first", s.root)
66			}
67			return err
68		}
69		defer lock.Close()
70		mode := syscall.LOCK_SH
71		if exclusive {
72			mode = syscall.LOCK_EX
73		}
74		if err := syscall.Flock(int(lock.Fd()), mode); err != nil {
75			return err
76		}
77		defer syscall.Flock(int(lock.Fd()), syscall.LOCK_UN)
78		return fn()
79	}
80	
81	func (s *Store) Init() error {
82		return s.withLock(true, s.initLocked)
83	}
84	
85	func (s *Store) initLocked() error {
86		if err := os.MkdirAll(filepath.Join(s.root, "objects"), 0o755); err != nil {
87			return err
88		}
89		_, err := os.Stat(s.indexPath())
90		if errors.Is(err, os.ErrNotExist) {
91			return s.save(index{Entries: map[string]Entry{}})
92		}
93		return err
94	}
95	
96	func (s *Store) Put(name, source string) (Entry, error) {
97		if err := validateName(name); err != nil {
98			return Entry{}, err
99		}
100		if source == "" {
101			return Entry{}, errors.New("file is required")
102		}
103		var entry Entry
104		err := s.withLock(true, func() error {
105			if err := s.initLocked(); err != nil {
106				return err
107			}
108			in, err := os.Open(source)
109			if err != nil {
110				return err
111			}
112			defer in.Close()
113			tmp, err := os.CreateTemp(filepath.Join(s.root, "objects"), ".upload-*")
114			if err != nil {
115				return err
116			}
117			tmpName := tmp.Name()
118			defer os.Remove(tmpName)
119			hash := sha256.New()
120			size, copyErr := io.Copy(io.MultiWriter(tmp, hash), in)
121			closeErr := tmp.Close()
122			if copyErr != nil {
123				return copyErr
124			}
125			if closeErr != nil {
126				return closeErr
127			}
128			digest := hex.EncodeToString(hash.Sum(nil))
129			object := s.objectPath(digest)
130			if _, err := os.Stat(object); errors.Is(err, os.ErrNotExist) {
131				if err := os.Rename(tmpName, object); err != nil {
132					return err
133				}
134			}
135			idx, err := s.load()
136			if err != nil {
137				return err
138			}
139			entry = Entry{Name: name, Digest: digest, Size: size, CreatedAt: time.Now().UTC()}
140			idx.Entries[name] = entry
141			return s.save(idx)
142		})
143		if err != nil {
144			return Entry{}, err
145		}
146		return entry, nil
147	}
148	
149	func (s *Store) List() ([]Entry, error) {
150		var entries []Entry
151		err := s.withLock(false, func() error {
152			idx, err := s.load()
153			if err != nil {
154				return err
155			}
156			entries = make([]Entry, 0, len(idx.Entries))
157			for _, entry := range idx.Entries {
158				entries = append(entries, entry)
159			}
160			return nil
161		})
162		if err != nil {
163			return nil, err
164		}
165		sort.Slice(entries, func(i, j int) bool { return entries[i].Name < entries[j].Name })
166		return entries, nil
167	}
168	
169	func (s *Store) Verify() (int, error) {
170		entries, err := s.List()
171		if err != nil {
172			return 0, err
173		}
174		for _, entry := range entries {
175			if err := s.verifyObject(entry); err != nil {
176				return 0, fmt.Errorf("verify %q: %w", entry.Name, err)
177			}
178		}
179		return len(entries), nil
180	}
181	
182	// verifyObject checks that the content object for entry exists and that its
183	// actual size and SHA-256 match the recorded metadata.
184	func (s *Store) verifyObject(entry Entry) error {
185		file, err := os.Open(s.objectPath(entry.Digest))
186		if err != nil {
187			return err
188		}
189		hash := sha256.New()
190		size, copyErr := io.Copy(hash, file)
191		closeErr := file.Close()
192		if copyErr != nil || closeErr != nil {
193			return errors.New("read failed")
194		}
195		if size != entry.Size || hex.EncodeToString(hash.Sum(nil)) != entry.Digest {
196			return errors.New("content mismatch")
197		}
198		return nil
199	}
200	
201	func (s *Store) load() (index, error) {
202		data, err := os.ReadFile(s.indexPath())
203		if err != nil {
204			return index{}, err
205		}
206		var idx index
207		if err := json.Unmarshal(data, &idx); err != nil {
208			return index{}, err
209		}
210		if idx.Entries == nil {
211			idx.Entries = map[string]Entry{}
212		}
213		return idx, nil
214	}
215	
216	func (s *Store) save(idx index) error {
217		data, err := json.MarshalIndent(idx, "", "  ")
218		if err != nil {
219			return err
220		}
221		data = append(data, '\n')
222		tmp, err := os.CreateTemp(s.root, ".index-*")
223		if err != nil {
224			return err
225		}
226		tmpName := tmp.Name()
227		defer os.Remove(tmpName)
228		if _, err := tmp.Write(data); err != nil {
229			tmp.Close()
230			return err
231		}
232		if err := tmp.Close(); err != nil {
233			return err
234		}
235		return os.Rename(tmpName, s.indexPath())
236	}
237	
238	func (s *Store) indexPath() string               { return filepath.Join(s.root, "index.json") }
239	func (s *Store) lockPath() string                { return filepath.Join(s.root, ".lock") }
240	func (s *Store) objectPath(digest string) string { return filepath.Join(s.root, "objects", digest) }
241	
242	func validateName(name string) error {
243		if strings.TrimSpace(name) == "" || filepath.IsAbs(name) || name == "." || name == ".." || strings.HasPrefix(name, "../") || strings.Contains(name, "\\") {
244			return errors.New("name must be a nonempty relative slash-separated path")
245		}
246		clean := filepath.Clean(name)
247		if clean != name || strings.HasPrefix(clean, "../") {
248			return errors.New("name must be normalized and remain within the vault namespace")
249		}
250		return nil
251	}
